const PROGRAM_NAME = 'test13_executable';
const USAGE_LINE = `usage: ${PROGRAM_NAME} [-h] --a A\n`;
const HELP_TEXT = `${USAGE_LINE}\noptions:\n  -h, --help  show this help message and exit\n  --a A\n`;

function isDigit(character) {
  return character >= '0' && character <= '9';
}

function isNegativeNumberLike(token) {
  if (token.length < 2 || token[0] !== '-' || token[1] === '-') {
    return false;
  }

  let hasDigit = false;
  let hasDot = false;

  for (let index = 1; index < token.length; index += 1) {
    const character = token[index];

    if (character === '_') {
      continue;
    }

    if (character === '.') {
      if (hasDot) {
        return false;
      }

      hasDot = true;
      continue;
    }

    if (!isDigit(character)) {
      return false;
    }

    hasDigit = true;
  }

  return hasDigit;
}

export function parseCommandLine(argv) {
  let value = '';
  let hasValue = false;
  const extras = [];
  let afterDoubleDash = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (afterDoubleDash) {
      extras.push(token);
      continue;
    }

    if (token === '--') {
      afterDoubleDash = true;
      continue;
    }

    if (token === '-h' || token === '--help') {
      return { help: true };
    }

    if (token === '--a') {
      const nextToken = argv[index + 1];

      if (
        nextToken === undefined ||
        nextToken === '--' ||
        (nextToken.startsWith('-') && !isNegativeNumberLike(nextToken))
      ) {
        return {
          error: {
            kind: 'missing_value',
          },
        };
      }

      value = nextToken;
      hasValue = true;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      value = token.slice(4);
      hasValue = true;
      continue;
    }

    extras.push(token);
  }

  if (!hasValue) {
    return {
      error: {
        kind: 'missing_required',
      },
    };
  }

  if (extras.length > 0) {
    return {
      error: {
        kind: 'unrecognized',
        extras,
      },
    };
  }

  return { value };
}

export function renderHelp() {
  return HELP_TEXT;
}

export function renderError(error) {
  if (error.kind === 'missing_value') {
    return `${USAGE_LINE}${PROGRAM_NAME}: error: argument --a: expected one argument\n`;
  }

  if (error.kind === 'unrecognized') {
    return `${USAGE_LINE}${PROGRAM_NAME}: error: unrecognized arguments: ${error.extras.join(' ')}\n`;
  }

  return `${USAGE_LINE}${PROGRAM_NAME}: error: the following arguments are required: --a\n`;
}

