export function stringNode(value) {
  return {
    nodeType: 'scalar',
    scalarType: 'string',
    value,
  };
}

export function boolNode(value) {
  return {
    nodeType: 'scalar',
    scalarType: 'bool',
    value: value === true,
  };
}

export function nullNode() {
  return {
    nodeType: 'scalar',
    scalarType: 'null',
    value: null,
  };
}

export function intNode(canonical, numericValue) {
  return {
    nodeType: 'scalar',
    scalarType: 'int',
    canonical,
    value: numericValue,
  };
}

export function floatNode(canonical, numericValue) {
  return {
    nodeType: 'scalar',
    scalarType: 'float',
    canonical,
    value: numericValue,
  };
}

export function sequenceNode(items = []) {
  return {
    nodeType: 'sequence',
    items,
  };
}

export function mappingNode(entries = []) {
  return {
    nodeType: 'mapping',
    entries,
  };
}

export function isScalar(node) {
  return node !== null && node !== undefined && node.nodeType === 'scalar';
}

export function isSequence(node) {
  return node !== null && node !== undefined && node.nodeType === 'sequence';
}

export function isMapping(node) {
  return node !== null && node !== undefined && node.nodeType === 'mapping';
}

export function isEmptyCollection(node) {
  return (
    (isSequence(node) && node.items.length === 0) ||
    (isMapping(node) && node.entries.length === 0)
  );
}

export function scalarIdentity(node) {
  if (!isScalar(node)) {
    return null;
  }

  if (node.scalarType === 'string') {
    return `string:${node.value}`;
  }

  if (node.scalarType === 'bool') {
    return `bool:${node.value ? 'true' : 'false'}`;
  }

  if (node.scalarType === 'null') {
    return 'null:null';
  }

  return `${node.scalarType}:${node.canonical}`;
}

export function sameScalarKey(left, right) {
  const leftIdentity = scalarIdentity(left);
  const rightIdentity = scalarIdentity(right);
  return leftIdentity !== null && leftIdentity === rightIdentity;
}

export function upsertMappingEntry(entries, key, value) {
  for (let index = 0; index < entries.length; index += 1) {
    if (sameScalarKey(entries[index].key, key)) {
      entries[index].value = value;
      return;
    }
  }

  entries.push({ key, value });
}

